--sgima
              local function ShowExecutorWarning()
    local Camera = workspace.CurrentCamera
    local ViewportSize = Camera.ViewportSize
    local BoxSize = Vector2.new(450, 150)
    local CenterX = ViewportSize.X / 2
    local CenterY = ViewportSize.Y / 2
    local BoxPosition = Vector2.new(CenterX - (BoxSize.X / 2), CenterY - (BoxSize.Y / 2))

    local Background = Drawing.new("Square")
    Background.Visible = true
    Background.Transparency = 0.8
    Background.Color = Color3.fromRGB(20, 20, 20)
    Background.Filled = true
    Background.Size = BoxSize
    Background.Position = BoxPosition
    Background.ZIndex = 1000

    local Border = Drawing.new("Square")
    Border.Visible = true
    Border.Transparency = 1
    Border.Color = Color3.fromRGB(255, 60, 60)
    Border.Thickness = 2
    Border.Filled = false
    Border.Size = BoxSize
    Border.Position = BoxPosition
    Border.ZIndex = 1001

    local Title = Drawing.new("Text")
    Title.Visible = true
    Title.Text = "MISSING DEPENDENCIES"
    Title.Size = 22
    Title.Center = true
    Title.Outline = true
    Title.Color = Color3.fromRGB(255, 60, 60)
    Title.Position = Vector2.new(CenterX, CenterY - 50)
    Title.ZIndex = 1002

    local Message = Drawing.new("Text")
    Message.Visible = true
    Message.Size = 18
    Message.Center = true
    Message.Outline = true
    Message.Color = Color3.fromRGB(240, 240, 240)
    Message.Position = Vector2.new(CenterX, CenterY - 10)
    Message.ZIndex = 1002
    Message.Text = "Your executor does not support\n'hookmetamethod' or 'getnamecallmethod'.\nSilent Aim cannot run."

    task.delay(8, function()
        Background:Remove()
        Border:Remove()
        Title:Remove()
        Message:Remove()
    end)
end

if not hookmetamethod or not getnamecallmethod then
    ShowExecutorWarning()
